import 'package:flutter/material.dart';
import '../data/app_database.dart';
class SettingsPage extends StatefulWidget{const SettingsPage({super.key});@override State<SettingsPage> createState()=>_S();}
class _S extends State<SettingsPage>{final name=TextEditingController(),phone=TextEditingController(),address=TextEditingController(),currency=TextEditingController(text:'AFN');String type='General Store';bool loading=true;static const types=['General Store','Retail Store','Pharmacy','Oil / Fuel Pump','Other'];@override void initState(){super.initState();load();}Future<void> load()async{final p=await AppDatabase.instance.getBusinessProfile();if(p!=null){name.text=p['business_name']?.toString()??'';phone.text=p['phone']?.toString()??'';address.text=p['address']?.toString()??'';type=p['business_type']?.toString()??'General Store';currency.text=p['currency']?.toString()??'AFN';}if(mounted)setState(()=>loading=false);}Future<void> save()async{await AppDatabase.instance.saveBusinessProfile(businessName:name.text.trim().isEmpty?'My Business':name.text.trim(),businessType:type,phone:phone.text.trim(),address:address.text.trim(),currency:currency.text.trim().isEmpty?'AFN':currency.text.trim());if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Business settings saved')));}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Business Settings')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Business name')),const SizedBox(height:12),DropdownButtonFormField<String>(value:type,items:types.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>type=v??type),decoration:const InputDecoration(labelText:'Business type')),const SizedBox(height:12),TextField(controller:phone,decoration:const InputDecoration(labelText:'Phone')),const SizedBox(height:12),TextField(controller:address,decoration:const InputDecoration(labelText:'Address')),const SizedBox(height:12),TextField(controller:currency,decoration:const InputDecoration(labelText:'Currency')),const SizedBox(height:20),FilledButton(onPressed:save,child:const Text('Save Settings'))]));}
